#include <iostream>
#include <chrono>
using namespace std;
using namespace chrono;

int main() {
    auto start = steady_clock::now();
    volatile int sum = 0;
    for (int i = 0; i < 1000000; i++) sum += i;
    auto end = steady_clock::now();
    auto ms = duration_cast<milliseconds>(end - start).count();
    cout << "Elapsed: " << ms << " ms" << endl;
    return 0;
}
